export function loadTasks(storage) {
  try {
    const data = JSON.parse(storage.getItem('tasks') || '[]');
    return Array.isArray(data) && data.every(t => typeof t.id === 'string' && typeof t.title === 'string' && typeof t.completed === 'boolean') ? data : [];
  } catch { return []; }
}
export function saveTasks(storage, tasks) { storage.setItem('tasks', JSON.stringify(tasks)); }

