export function addTask(tasks, id, title) {
  if (!title.trim()) throw new Error('Empty title');
  return [...tasks, { id, title: title.trim(), completed: false }];
}
export function toggleTask(tasks, id) { return tasks.map(t => t.id === id ? { ...t, completed: !t.completed } : t); }
export function filterTasks(tasks, filter = 'all') { return tasks.filter(t => filter === 'all' || (filter === 'completed' ? t.completed : !t.completed)); }
export function remainingCount(tasks) { return tasks.filter(t => !t.completed).length; }

files.src/task-view.js:
export function renderTasks(tasks, filter = 'all') {
  const visible = tasks.filter(t => filter === 'all' || (filter === 'completed' ? t.completed : !t.completed));
  return { filter, remaining: tasks.filter(t => !t.completed).length, items: visible.map(t => ({ ...t })) };
}

