import assert from 'node:assert/strict';
import { loadTasks, saveTasks } from '../src/task-store.js';
test('persistence round trip and malformed data', () => {
  let raw = ''; const storage = { getItem: () => raw, setItem: (_, value) => { raw = value; } };
  const tasks = [{ id: '1', title: 'Demo', completed: false }];
  saveTasks(storage, tasks); assert.deepEqual(loadTasks(storage), tasks);
  raw = '{broken'; assert.deepEqual(loadTasks(storage), []);
  raw = '{}'; assert.deepEqual(loadTasks(storage), []);
});

