import { loadTasks, saveTasks } from './task-store.js';
import { addTask, toggleTask } from './task-service.js';
import { renderTasks } from './task-view.js';
export function createApp(storage) {
  let tasks = loadTasks(storage);
  return {
    add(id, title) { tasks = addTask(tasks, id, title); saveTasks(storage, tasks); },
    toggle(id) { tasks = toggleTask(tasks, id); saveTasks(storage, tasks); },
    view(filter = 'all') { return renderTasks(tasks, filter); }
  };
}

