import test from 'node:test';
import assert from 'node:assert/strict';
import { createApp } from '../src/app.js';
import { addTask, filterTasks, remainingCount } from '../src/task-service.js';
test('add, toggle, filter, count and reload', () => {
  let raw = ''; const storage = { getItem: () => raw, setItem: (_, value) => { raw = value; } };
  const app = createApp(storage); app.add('1', 'First'); app.add('2', 'Second'); app.toggle('1');
  assert.equal(app.view().remaining, 1);
  assert.equal(app.view('completed').items[0].id, '1');
  assert.equal(app.view('active').items[0].id, '2');
  assert.deepEqual(createApp(storage).view(), app.view());
  assert.throws(() => app.add('3', '  '), /Empty title/);
});
test('filters do not mutate source and counts ignore current filter', () => {
  const tasks = addTask([], '1', 'Demo'); const before = JSON.stringify(tasks);
  assert.deepEqual(filterTasks(tasks, 'completed'), []);
  assert.equal(remainingCount(tasks), 1); assert.equal(JSON.stringify(tasks), before);
});

